<script lang="ts">
 import type {ConceptVisual} from '$lib/concepts';
 let {diagram,number,lang}:{diagram:ConceptVisual;number:number;lang:'zh'|'en'}=$props();
</script>
{#snippet node(index:number)}<div class="node" data-node={index} id={number===3&&index===1?`flow-check-${lang}`:undefined}><strong>{diagram.items[index].title}</strong><p>{diagram.items[index].body}</p></div>{/snippet}
{#snippet arrow()}<svg class="arrow" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3v24m-7-7 7 7 7-7" fill="none" stroke="currentColor" stroke-width="2"/></svg>{/snippet}
<figure class="flow-architecture" data-figure={number}>
 <figcaption><strong>{diagram.caption}</strong></figcaption>
 {#if number===1}
  <ol class="meal">{#each diagram.items as item,i}<li><strong>{item.title}</strong><p>{item.body}</p></li>{#if i<4}<li class="next" aria-hidden="true">→</li>{/if}{/each}</ol>
 {:else if number===2}
  <div class="restaurant">{@render node(0)}{@render arrow()}{@render node(1)}<div class="receivers">{#each [2,3,4] as index}<div class="receiver">{@render arrow()}{@render node(index)}</div>{/each}</div></div>
 {:else if number===3}
  <div class="intake">{@render node(0)}{@render arrow()}{@render node(1)}{@render arrow()}<div class="decision">{@render node(2)}</div><div class="branches"><section class="correction" aria-label={diagram.items[3].title}>{@render arrow()}{@render node(3)}{@render arrow()}{@render node(4)}<p class="return"><a href={`#flow-check-${lang}`}>↶ {lang==='zh'?'回到「按下檢查」':'Return to Press Check'}</a></p></section><section aria-label={diagram.items[5].title}>{@render arrow()}{@render node(5)}{@render arrow()}{@render node(6)}</section></div></div>
 {:else if number===4}
  <div class="runtime">{@render node(0)}{@render arrow()}{@render node(1)}<div class="locations"><section class="host"><h3>{lang==='zh'?'Streamlit 執行主機':'Streamlit host'}</h3><span class="arrow" aria-hidden="true">↕</span><div class="process"><h4>{lang==='zh'?'同一個 Python 程序':'One Python process'}</h4>{@render node(2)}<div class="internals">{#each [3,4] as index}<div><p class="peer-label">{diagram.items[2].title} ↔</p>{@render node(index)}</div>{/each}</div></div></section><section class="download"><h3>{lang==='zh'?'瀏覽器 → 下載':'Browser → download'}</h3>{@render arrow()}{@render node(5)}</section></div></div>
 {:else}
  <ol class="levels">{#each diagram.items as item,i}<li><strong>{item.title}</strong><p>{item.body}</p></li>{#if i<3}<li class="zoom" aria-hidden="true">↓</li>{/if}{/each}</ol>
 {/if}
 <p class="description">{diagram.description}</p>
 <a href={`/images/aase/m06-01-${number}-${lang}.svg`} target="_blank" rel="noreferrer">{lang==='zh'?'開啟／下載原尺寸 SVG':'Open / download full-size SVG'}</a>
</figure>
